function parseCsv(text) {
  const rows = [];
  let row = [], field = '', inQ = false;
  const s = String(text || '').replace(/^﻿/, '');
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inQ) {
      if (c === '"' && s[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') inQ = false;
      else field += c;
    } else if (c === '"') inQ = true;
    else if (c === ',' || c === ';') { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && s[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.some(v => v !== '')) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some(v => v !== '')) rows.push(row);
  if (!rows.length) return [];
  const head = rows[0].map(h => h.trim());
  return rows.slice(1).map(r => Object.fromEntries(head.map((h, i) => [h, (r[i] || '').trim()])));
}

function toCsv(records, columns) {
  const cols = columns || [...new Set(records.flatMap(r => Object.keys(r)))];
  const esc = v => {
    v = v == null ? '' : String(v);
    // evita injeção de fórmulas ao abrir no Excel/Sheets
    if (/^[=+\-@]/.test(v)) v = "'" + v;
    return /[",\n\r;]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v;
  };
  return [cols.join(','), ...records.map(r => cols.map(c => esc(r[c])).join(','))].join('\n');
}

function normalizeDomain(url) {
  if (!url) return '';
  let h = String(url).trim().toLowerCase();
  h = h.replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split(/[\/?#]/)[0].split(':')[0];
  return /^[a-z0-9.-]+\.[a-z]{2,}$/.test(h) ? h : '';
}

function normalizeCnpj(v) {
  const d = String(v || '').replace(/\D/g, '');
  return d.length === 14 ? d : '';
}

function validCnpj(v) {
  const d = normalizeCnpj(v);
  if (!d || /^(\d)\1+$/.test(d)) return false;
  const calc = len => {
    let sum = 0, pos = len - 7;
    for (let i = len; i >= 1; i--) { sum += d[len - i] * pos--; if (pos < 2) pos = 9; }
    const r = sum % 11;
    return r < 2 ? 0 : 11 - r;
  };
  return calc(12) === +d[12] && calc(13) === +d[13];
}

function normalizeName(n) {
  return String(n || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/\b(ltda|me|epp|eireli|s\/?a|sa|industria|comercio|e)\b/g, ' ')
    .replace(/[^a-z0-9]+/g, ' ').trim();
}

// Chaves fortes: CNPJ e domínio. Chave fraca (nome+UF) só sinaliza "possível duplicado".
function keysFor(lead) {
  return {
    cnpj: validCnpj(lead.cnpj) ? normalizeCnpj(lead.cnpj) : '',
    domain: normalizeDomain(lead.site),
    weak: normalizeName(lead.nome) && lead.uf ? normalizeName(lead.nome) + '|' + String(lead.uf).toUpperCase() : '',
  };
}

function findDuplicate(candidate, existing) {
  const k = keysFor(candidate);
  for (const e of existing) {
    const ek = keysFor(e);
    if (k.cnpj && k.cnpj === ek.cnpj) return { lead: e, match: 'cnpj', strong: true };
    if (k.domain && k.domain === ek.domain) return { lead: e, match: 'dominio', strong: true };
  }
  for (const e of existing) {
    const ek = keysFor(e);
    if (k.weak && k.weak === ek.weak) return { lead: e, match: 'nome_uf', strong: false };
  }
  return null;
}

// Preenche apenas campos vazios; nunca sobrescreve dado existente.
function mergeLead(existing, incoming) {
  const out = { ...existing };
  for (const [k, v] of Object.entries(incoming)) if (!out[k] && v) out[k] = v;
  return out;
}

const FACTORS = {
  A: 'Compatibilidade com fabricação/montagem',
  B: 'Complexidade aparente dos equipamentos',
  C: 'Indícios de produção sob encomenda',
  D: 'Número de etapas/tipos de produto',
  E: 'Porte e público-alvo',
  F: 'Canal comercial apropriado',
  G: 'Operação produtiva própria',
};
const DEFAULT_WEIGHTS = { A: 25, B: 15, C: 20, D: 10, E: 10, F: 10, G: 10 };

// factors: { A: { value: 0..1 | null, level: 'fato'|'inferencia'|'hipotese', evidence: [urls] } }
// Fator desconhecido (value null) NÃO penaliza: entra com valor neutro e fica listado em "unknown".
function computeScore(factors, weights = DEFAULT_WEIGHTS, neutral = 0.5) {
  const total = Object.values(weights).reduce((a, b) => a + b, 0) || 1;
  let sum = 0;
  const breakdown = {}, unknown = [];
  for (const k of Object.keys(weights)) {
    const f = factors[k] || {};
    const known = typeof f.value === 'number' && !isNaN(f.value);
    const v = known ? Math.min(1, Math.max(0, f.value)) : neutral;
    if (!known) unknown.push(k);
    const pts = (v * weights[k] * 100) / total;
    breakdown[k] = { points: Math.round(pts * 10) / 10, weight: weights[k], known, level: f.level || (known ? 'inferencia' : 'desconhecido'), evidence: f.evidence || [] };
    sum += pts;
  }
  const knownWeight = Object.keys(weights).filter(k => !unknown.includes(k)).reduce((a, k) => a + weights[k], 0);
  return { score: Math.round(sum), breakdown, unknown, confidence: Math.round((knownWeight / total) * 100) / 100 };
}

function norm(v) { return String(v || '').trim().toLowerCase(); }

function isSuppressed(lead, list) {
  const emails = new Set(), domains = new Set(), ids = new Set();
  for (const s of list || []) {
    if (s.email) emails.add(norm(s.email));
    if (s.dominio) domains.add(norm(s.dominio));
    if (s.lead_id) ids.add(s.lead_id);
  }
  const d = normalizeDomain(lead.site);
  const em = norm(lead.email);
  if (ids.has(lead.id)) return true;
  if (d && domains.has(d)) return true;
  if (em && (emails.has(em) || domains.has(em.split('@')[1]))) return true;
  return false;
}

const DEFAULT_STAGES = [
  'identificada', 'pesquisada', 'qualificado', 'aguardando_aprovacao', 'aprovada', 'contato_realizado',
  'resposta_recebida', 'reuniao_agendada', 'diagnostico_realizado', 'demonstracao_apresentada',
  'proposta_enviada', 'negociacao', 'cliente', 'perdido',
];
const PROMO_STAGES = ['aguardando_aprovacao', 'aprovada'];

// Transição: registra data/ator e aplica regras de interrupção.
function transition(lead, to, opts = {}) {
  const stages = opts.stages || DEFAULT_STAGES;
  if (!stages.includes(to)) throw new Error('Etapa inválida: ' + to);
  if (lead.nao_contatar && PROMO_STAGES.concat('contato_realizado').includes(to)) {
    throw new Error('Lead marcado como não contatar: ação promocional bloqueada');
  }
  const at = opts.at || new Date().toISOString();
  const entry = { de: lead.status, para: to, em: at, por: opts.by || 'usuario', motivo: opts.reason || '' };
  const next = { ...lead, status: to, atualizado_em: at, historico: [...(lead.historico || []), entry] };
  if (to === 'perdido' && !opts.reason) throw new Error('Informe o motivo da perda');
  if (to === 'resposta_recebida' || to === 'perdido') next.proxima_acao = next.proxima_acao || '';
  return next;
}

function markDoNotContact(lead, opts = {}) {
  const at = opts.at || new Date().toISOString();
  return {
    ...lead, nao_contatar: true, proxima_acao: '', atualizado_em: at,
    historico: [...(lead.historico || []), { de: lead.status, para: lead.status, em: at, por: opts.by || 'usuario', motivo: 'nao_contatar: ' + (opts.reason || '') }],
  };
}

function suggestNextAction(lead) {
  if (lead.nao_contatar) return 'Nenhuma (não contatar)';
  const m = {
    identificada: 'Pesquisar a empresa em fontes oficiais',
    pesquisada: 'Qualificar e revisar a pontuação',
    qualificado: 'Gerar rascunho de abordagem',
    aguardando_aprovacao: 'Revisar, editar e aprovar o rascunho',
    aprovada: 'Enviar manualmente e marcar como enviado',
    contato_realizado: 'Aguardar resposta; revisar manualmente após alguns dias úteis',
    resposta_recebida: 'Responder e propor 20 min de conversa',
    reuniao_agendada: 'Preparar roteiro de diagnóstico',
    diagnostico_realizado: 'Avaliar demonstração',
    demonstracao_apresentada: 'Avaliar proposta',
    proposta_enviada: 'Fazer acompanhamento manual',
    negociacao: 'Definir próximos passos com o decisor',
  };
  return m[lead.status] || '';
}

const DEFAULT_RULES = {
  maxWords: 180,
  // Afirmações de dor que exigem evidência; o rascunho não pode afirmá-las.
  bannedClaims: [/vocês? (usa|usam|trabalha|trabalham) com planilhas?/i, /sofre[mr]?\b/i, /atrasos? (constantes|frequentes)/i, /desperd[ií]cio/i, /falta de estoque/i, /garantimos?/i, /aumente .* em \d+%/i, /resultados? garantidos?/i],
  placeholders: /\[[^\]]+\]|\{\{[^}]+\}\}/,
};

// cfg: { allowedLinks:[urls configuradas], nonExistingFeatures:[termos], suppression:[...] }
function validateDraft(draft, lead, cfg = {}) {
  const errors = [], warnings = [];
  const body = String(draft.corpo || ''), subject = String(draft.assunto || '');
  const rules = { ...DEFAULT_RULES, ...(cfg.rules || {}) };
  if (!subject.trim()) errors.push('Assunto vazio');
  if (!body.trim()) errors.push('Corpo vazio');
  if (rules.placeholders.test(subject + body)) errors.push('Placeholders não preenchidos');
  if (body.split(/\s+/).filter(Boolean).length > rules.maxWords) warnings.push('Mensagem longa');
  for (const re of rules.bannedClaims) if (re.test(body)) errors.push('Afirmação sem evidência: ' + re);
  for (const t of cfg.nonExistingFeatures || []) if (t && body.toLowerCase().includes(t.toLowerCase())) errors.push('Menciona funcionalidade inexistente: ' + t);
  const allowed = new Set((cfg.allowedLinks || []).map(u => u.replace(/\/$/, '')));
  for (const u of body.match(/https?:\/\/[^\s)>"]+/g) || []) {
    if (!allowed.has(u.replace(/[.,;]$/, '').replace(/\/$/, ''))) errors.push('Link não configurado: ' + u);
  }
  if (!lead.fontes || !lead.fontes.length) errors.push('Lead sem fonte registrada');
  if (lead.email && !lead.email_fonte) errors.push('E-mail sem URL de origem');
  if (lead.nao_contatar || isSuppressed(lead, cfg.suppression)) errors.push('Lead em lista de supressão');
  return { ok: errors.length === 0, errors, warnings };
}

// Conversão só é exibida quando o denominador atinge minSample; senão, "amostra insuficiente".
function computeMetrics(leads, opts = {}) {
  const stages = opts.stages || DEFAULT_STAGES;
  const minSample = opts.minSample || 20;
  const reached = Object.fromEntries(stages.map(s => [s, 0]));
  const idx = s => stages.indexOf(s);
  for (const l of leads) {
    const visited = new Set((l.historico || []).map(h => h.para).concat(l.status));
    // etapa atingida = visitada ou posterior à maior visitada (exceto "perdido")
    const max = Math.max(-1, ...[...visited].filter(s => s !== 'perdido').map(idx));
    stages.forEach((s, i) => { if (s !== 'perdido' && (i <= max || visited.has(s))) reached[s]++; });
    if (visited.has('perdido')) reached['perdido']++;
  }
  const conversions = [];
  const chain = stages.filter(s => s !== 'perdido');
  for (let i = 1; i < chain.length; i++) {
    const from = reached[chain[i - 1]], to = reached[chain[i]];
    conversions.push({ de: chain[i - 1], para: chain[i], base: from, atingiram: to,
      taxa: from >= minSample ? Math.round((to / from) * 1000) / 10 : null,
      nota: from >= minSample ? 'observado' : 'amostra insuficiente (<' + minSample + ')' });
  }
  const count = (key, f = x => x) => {
    const o = {};
    for (const l of leads) { const v = f(l[key]) || 'não informado'; o[v] = (o[v] || 0) + 1; }
    return o;
  };
  const lost = {};
  for (const l of leads) if (l.status === 'perdido') { const m = l.motivo_perda || 'não informado'; lost[m] = (lost[m] || 0) + 1; }
  return {
    total: leads.length, porEtapa: reached, conversoes: conversions,
    porSegmento: count('segmento'), porFonte: count('fonte_aquisicao'), motivosPerda: lost,
    proximasAcoes: leads.filter(l => l.proxima_acao && !l.nao_contatar).map(l => ({ id: l.id, nome: l.nome, acao: l.proxima_acao, data: l.proxima_acao_data || '' })),
    tipo: 'observado',
  };
}

const STAGES = DEFAULT_STAGES;
const bool = v => ['true', 'sim', '1', 'x'].includes(String(v || '').toLowerCase());
const normLead = l => ({ ...l, nao_contatar: bool(l.nao_contatar) });
const cfgMap = rows => Object.fromEntries(rows.filter(r => r.json && r.json.chave).map(r => [r.json.chave, String(r.json.valor || '')]));
const list = s => String(s || '').split(';').map(x => x.trim()).filter(Boolean);
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const now = () => new Date().toISOString();
function requireToken(token) {
  const t = $env.REVIEW_UI_TOKEN;
  if (!t) throw new Error('REVIEW_UI_TOKEN não configurado: recusando requisição');
  if (token !== t) throw new Error('Não autorizado');
}
function hashId(s) { let h = 5381; for (const c of s) h = ((h * 33) ^ c.charCodeAt(0)) >>> 0; return 'L' + h.toString(36); }

